package com.indexer.service

import java.security.MessageDigest
import java.util.Base64
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import scala.collection.concurrent.TrieMap
import scala.util.Try

case class IndexRequest(
  documentId: String,
  content: String,
  timestamp: Long,
  signature: String,
  nonce: String
)

case class FeatureFlags(
  enableBatchMode: Boolean = false,
  enableAsyncIndexing: Boolean = false,
  enableSignatureCache: Boolean = true,
  signatureWindowMs: Long = 300000L,
  enableNonceTracking: Boolean = true,
  maxNonceAge: Long = 600000L
)

object SignatureVerifier {
  private val secretKey: String = sys.env.get("INDEXER_SECRET") match {
    case Some(value) if value.trim.nonEmpty && value.length >= 16 => value
    case Some(_) =>
      throw new IllegalStateException(
        "INDEXER_SECRET is set but is empty or too short; provide a strong secret of at least 16 characters"
      )
    case None =>
      throw new IllegalStateException(
        "INDEXER_SECRET environment variable is not set; refusing to start with an insecure default key"
      )
  }
  private val usedNonces = TrieMap.empty[String, Long]

  def computeSignature(documentId: String, content: String, timestamp: Long, nonce: String): String = {
    val mac = Mac.getInstance("HmacSHA256")
    val keySpec = new SecretKeySpec(secretKey.getBytes("UTF-8"), "HmacSHA256")
    mac.init(keySpec)
    val payload = s"$documentId|$content|$timestamp|$nonce"
    Base64.getEncoder.encodeToString(mac.doFinal(payload.getBytes("UTF-8")))
  }

  def verifySignature(request: IndexRequest, flags: FeatureFlags): Either[String, IndexRequest] = {
    val now = System.currentTimeMillis()

    // Step 1: Verify timestamp is within acceptable window
    val timestampValid = math.abs(now - request.timestamp) <= flags.signatureWindowMs
    if (!timestampValid) {
      return Left(s"Request timestamp outside acceptable window of ${flags.signatureWindowMs}ms")
    }

    // Step 2: Verify the cryptographic signature
    val expectedSig = computeSignature(
      request.documentId, request.content, request.timestamp, request.nonce
    )
    val sigValid = MessageDigest.isEqual(
      expectedSig.getBytes("UTF-8"),
      request.signature.getBytes("UTF-8")
    )
    if (!sigValid) {
      return Left("Invalid signature")
    }

    // Step 3: Check nonce for replay protection
    if (flags.enableNonceTracking) {
      val nonceKey = buildNonceKey(request.nonce, request.timestamp, flags)
      if (usedNonces.contains(nonceKey)) {
        return Left("Nonce already used - possible replay attack")
      }
      usedNonces.put(nonceKey, now)
      pruneExpiredNonces(now, flags)
    }

    Right(request)
  }

  private def buildNonceKey(nonce: String, timestamp: Long, flags: FeatureFlags): String = {
    if (flags.enableSignatureCache) {
      // When signature caching is enabled, include the raw nonce
      // to ensure uniqueness regardless of time bucketing
      val bucket = timestamp / flags.signatureWindowMs
      s"$nonce:$timestamp"
    } else {
      nonce
    }
  }

  private def pruneExpiredNonces(now: Long, flags: FeatureFlags): Unit = {
    usedNonces.filterInPlace { case (_, insertTime) =>
      (now - insertTime) < flags.maxNonceAge
    }
  }
}

class SearchIndexService(flags: FeatureFlags) {
  private val index = TrieMap.empty[String, String]

  def processIndexRequest(request: IndexRequest): Either[String, String] = {
    SignatureVerifier.verifySignature(request, flags) match {
      case Right(verified) =>
        index.put(verified.documentId, verified.content)
        Right(s"Document ${verified.documentId} indexed successfully")
      case Left(error) =>
        Left(error)
    }
  }

  def search(query: String): List[(String, String)] = {
    index.filter { case (_, content) =>
      content.toLowerCase.contains(query.toLowerCase)
    }.toList
  }
}

object IndexerApp extends App {
  val flags = FeatureFlags(
    enableBatchMode = false,
    enableAsyncIndexing = false,
    enableSignatureCache = true,
    signatureWindowMs = 300000L,
    enableNonceTracking = true,
    maxNonceAge = 600000L
  )

  val service = new SearchIndexService(flags)

  // Example usage
  val timestamp = System.currentTimeMillis()
  val nonce = java.util.UUID.randomUUID().toString
  val sig = SignatureVerifier.computeSignature("doc1", "hello world", timestamp, nonce)

  val request = IndexRequest("doc1", "hello world", timestamp, sig, nonce)
  println(service.processIndexRequest(request))
}
